-- Unverified source assertions only. No financial facts or approved scope generations are changed.
ALTER TABLE plugin_finance_book ADD CONSTRAINT finance_movement_book_entity UNIQUE(tenant_id,id,legal_entity_id);
ALTER TABLE plugin_finance_line ADD CONSTRAINT finance_movement_line_account UNIQUE(tenant_id,book_id,year_id,journal_id,line_no,account_id);
ALTER TABLE plugin_finance_posting ADD CONSTRAINT finance_movement_posting_sequence UNIQUE(tenant_id,book_id,year_id,journal_id,posting_seq);
ALTER TABLE plugin_finance_original ADD CONSTRAINT finance_movement_original_hash UNIQUE(tenant_id,book_id,year_id,id,sha256);
CREATE TABLE plugin_finance_cash_registration_guard (
 tenant_id uuid NOT NULL,book_id uuid NOT NULL,year_id uuid NOT NULL,registration_version bigint NOT NULL DEFAULT 0 CHECK(registration_version>=0),
 PRIMARY KEY(tenant_id,book_id,year_id),FOREIGN KEY(tenant_id,book_id,year_id) REFERENCES plugin_finance_year_guard(tenant_id,book_id,year_id));
CREATE TABLE plugin_finance_cash_movement_registration (
 tenant_id uuid NOT NULL,book_id uuid NOT NULL,year_id uuid NOT NULL,id uuid NOT NULL,legal_entity_id uuid NOT NULL,
 schema_version text NOT NULL DEFAULT 'cash-movement-registration/1' CHECK(schema_version='cash-movement-registration/1'),
 source_system text NOT NULL CHECK(source_system IN('BANK_STATEMENT_MANUAL_V1','CASH_BOOK_MANUAL_V1','CASH_RECEIPT_MANUAL_V1')),
 source_movement_key text NOT NULL CHECK(length(source_movement_key) BETWEEN 1 AND 160),source_document_id text NOT NULL CHECK(length(source_document_id) BETWEEN 1 AND 160),source_document_version integer NOT NULL CHECK(source_document_version>0),source_row_reference text NOT NULL CHECK(length(source_row_reference) BETWEEN 1 AND 120),evidence_kind text NOT NULL,
 source_original_id uuid NOT NULL,source_original_sha256 text NOT NULL CHECK(source_original_sha256~'^[a-f0-9]{64}$'),
 cash_scope_revision_id uuid NOT NULL,approved_scope_version bigint NOT NULL CHECK(approved_scope_version>0),scope_content_digest text NOT NULL CHECK(scope_content_digest~'^[a-f0-9]{64}$'),account_id uuid NOT NULL,
 occurred_date date NOT NULL,direction text NOT NULL CHECK(direction IN('IN','OUT')),amount numeric(28,8) NOT NULL CHECK(amount>0 AND amount=trunc(amount,2)),currency text NOT NULL DEFAULT 'CNY' CHECK(currency='CNY'),transaction_kind text NOT NULL,
 journal_id uuid NOT NULL,line_no integer NOT NULL CHECK(line_no BETWEEN 1 AND 500),matched_journal_version bigint NOT NULL CHECK(matched_journal_version>0),posting_seq bigint NOT NULL CHECK(posting_seq>0),posting_digest text NOT NULL,
 business_digest text NOT NULL CHECK(business_digest~'^[a-f0-9]{64}$'),content_digest text NOT NULL CHECK(content_digest~'^[a-f0-9]{64}$'),content jsonb NOT NULL,
 prepared_by uuid NOT NULL,prepared_username text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 status text NOT NULL DEFAULT 'REGISTERED' CHECK(status IN('REGISTERED','VOIDED')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),content_version bigint NOT NULL DEFAULT 1 CHECK(content_version=1),
 verification_status text NOT NULL DEFAULT 'UNREVIEWED' CHECK(verification_status='UNREVIEWED'),classification_status text NOT NULL DEFAULT 'UNCLASSIFIED' CHECK(classification_status='UNCLASSIFIED'),report_contribution_enabled boolean NOT NULL DEFAULT false CHECK(NOT report_contribution_enabled),
 -- No downstream use API exists in this version. Future use protocols must replace this frozen guard.
 downstream_use_count bigint NOT NULL DEFAULT 0 CHECK(downstream_use_count=0),voided_by uuid,voided_at timestamptz,void_reason text,
 PRIMARY KEY(tenant_id,book_id,year_id,id),UNIQUE(tenant_id,source_system,source_movement_key),UNIQUE(tenant_id,source_original_sha256,source_row_reference),
 FOREIGN KEY(tenant_id,book_id,year_id) REFERENCES plugin_finance_cash_registration_guard(tenant_id,book_id,year_id),
 FOREIGN KEY(tenant_id,book_id,legal_entity_id) REFERENCES plugin_finance_book(tenant_id,id,legal_entity_id),
 FOREIGN KEY(tenant_id,book_id,year_id,cash_scope_revision_id,account_id) REFERENCES plugin_finance_cash_scope_item(tenant_id,book_id,year_id,scope_revision_id,account_id),
 FOREIGN KEY(tenant_id,book_id,year_id,source_original_id,source_original_sha256) REFERENCES plugin_finance_original(tenant_id,book_id,year_id,id,sha256),
 FOREIGN KEY(tenant_id,book_id,year_id,journal_id,line_no,account_id) REFERENCES plugin_finance_line(tenant_id,book_id,year_id,journal_id,line_no,account_id),
 FOREIGN KEY(tenant_id,book_id,year_id,journal_id,posting_seq) REFERENCES plugin_finance_posting(tenant_id,book_id,year_id,journal_id,posting_seq),
 CHECK((source_system='BANK_STATEMENT_MANUAL_V1' AND evidence_kind='BANK_STATEMENT') OR (source_system='CASH_BOOK_MANUAL_V1' AND evidence_kind='CASH_BOOK') OR (source_system='CASH_RECEIPT_MANUAL_V1' AND evidence_kind='CASH_RECEIPT')),
 CHECK((direction='IN' AND transaction_kind IN('ORDINARY_CUSTOMER_RECEIPT','ORDINARY_BORROWING_RECEIPT','ORDINARY_CAPITAL_RECEIPT')) OR (direction='OUT' AND transaction_kind IN('ORDINARY_SUPPLIER_PAYMENT','ORDINARY_PAYROLL','ORDINARY_TAX_PAYMENT','ORDINARY_PRINCIPAL_REPAYMENT'))));
CREATE UNIQUE INDEX finance_cash_movement_active_leg ON plugin_finance_cash_movement_registration(tenant_id,book_id,year_id,journal_id,line_no) WHERE status='REGISTERED';
CREATE INDEX finance_cash_movement_cursor ON plugin_finance_cash_movement_registration(tenant_id,book_id,year_id,created_at DESC,id DESC);
CREATE FUNCTION plugin_finance_cash_movement_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE scope_row record; scope_item record; leg record; original_row record; current_account jsonb; expected_item jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CASH_MOVEMENT_IMMUTABLE'; END IF;
 PERFORM 1 FROM plugin_finance_year_guard WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id FOR UPDATE;
 PERFORM 1 FROM plugin_finance_cash_registration_guard WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id FOR UPDATE;
 PERFORM 1 FROM plugin_finance_year y JOIN plugin_finance_period p ON (p.tenant_id,p.book_id,p.year_id)=(y.tenant_id,y.book_id,y.id) WHERE y.tenant_id=NEW.tenant_id AND y.book_id=NEW.book_id AND y.id=NEW.year_id AND y.year=extract(year FROM NEW.occurred_date) AND y.status='OPEN' AND y.precision_profile='V4' AND NOT y.precision_review_required AND p.month=extract(month FROM NEW.occurred_date) AND p.status='OPEN' FOR UPDATE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASH_MOVEMENT_YEAR_OR_PERIOD_CLOSED'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','version','voided_by','voided_at','void_reason']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','voided_by','voided_at','void_reason']) THEN RAISE EXCEPTION 'CASH_MOVEMENT_CONTENT_IMMUTABLE'; END IF;
  IF OLD.status<>'REGISTERED' OR NEW.status<>'VOIDED' OR NEW.version<>OLD.version+1 OR NEW.voided_by IS DISTINCT FROM OLD.prepared_by OR NEW.voided_at IS NULL OR coalesce(length(NEW.void_reason),0) NOT BETWEEN 1 AND 1000 OR OLD.downstream_use_count<>0 THEN RAISE EXCEPTION 'CASH_MOVEMENT_INVALID_VOID'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.status<>'REGISTERED' OR NEW.version<>1 OR NEW.voided_by IS NOT NULL OR NEW.voided_at IS NOT NULL OR NEW.void_reason IS NOT NULL THEN RAISE EXCEPTION 'CASH_MOVEMENT_INITIAL_REGISTERED_REQUIRED'; END IF;
 SELECT * INTO scope_row FROM plugin_finance_cash_scope_revision WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.cash_scope_revision_id;
 SELECT * INTO scope_item FROM plugin_finance_cash_scope_item WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND scope_revision_id=NEW.cash_scope_revision_id AND account_id=NEW.account_id;
 IF scope_row.status IS DISTINCT FROM 'APPROVED' OR scope_row.approved_scope_version IS DISTINCT FROM NEW.approved_scope_version OR scope_row.content_digest IS DISTINCT FROM NEW.scope_content_digest OR NEW.occurred_date NOT BETWEEN scope_row.period_start AND scope_row.period_end OR scope_item.qualification IS DISTINCT FROM 'INCLUDED' OR scope_item.restriction_kind IS DISTINCT FROM 'NONE' OR NOT scope_item.available_on_demand OR NOT scope_item.single_cash_instrument OR scope_item.instrument_kind IS DISTINCT FROM (CASE WHEN NEW.source_system='BANK_STATEMENT_MANUAL_V1' THEN 'DEMAND_DEPOSIT' ELSE 'CASH_ON_HAND' END) THEN RAISE EXCEPTION 'CASH_MOVEMENT_SCOPE_STALE'; END IF;
 SELECT j.status,j.date,j.version,j.number,j.summary,p.posting_seq,p.digest,l.debit,l.credit INTO leg FROM plugin_finance_journal j JOIN plugin_finance_line l ON (l.tenant_id,l.book_id,l.year_id,l.journal_id)=(j.tenant_id,j.book_id,j.year_id,j.id) JOIN plugin_finance_posting p ON (p.tenant_id,p.book_id,p.year_id,p.journal_id)=(j.tenant_id,j.book_id,j.year_id,j.id) WHERE j.tenant_id=NEW.tenant_id AND j.book_id=NEW.book_id AND j.year_id=NEW.year_id AND j.id=NEW.journal_id AND l.line_no=NEW.line_no AND l.account_id=NEW.account_id FOR UPDATE OF l;
 IF NOT FOUND OR leg.status<>'POSTED' OR leg.date<>NEW.occurred_date OR leg.version<>NEW.matched_journal_version OR leg.posting_seq IS DISTINCT FROM NEW.posting_seq OR leg.digest IS DISTINCT FROM NEW.posting_digest OR NOT ((NEW.direction='IN' AND leg.debit=NEW.amount AND leg.credit=0) OR (NEW.direction='OUT' AND leg.credit=NEW.amount AND leg.debit=0)) THEN RAISE EXCEPTION 'CASH_MOVEMENT_MATCH_INVALID'; END IF;
 SELECT * INTO original_row FROM plugin_finance_original WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.source_original_id;
 SELECT jsonb_build_object('id',id,'code',code,'name',name,'normalSide',normal_side,'category',category,'cashFlowCategory',cash_flow_category,'enabled',enabled,'purpose',purpose) INTO current_account FROM plugin_finance_account WHERE tenant_id=NEW.tenant_id AND book_id=NEW.book_id AND year_id=NEW.year_id AND id=NEW.account_id AND enabled AND category='ASSET' AND normal_side='DEBIT';
 SELECT value INTO expected_item FROM jsonb_array_elements(scope_row.content->'items') WHERE value->>'accountId'=NEW.account_id::text;
 IF current_account IS DISTINCT FROM scope_item.account_snapshot OR ((NEW.content->'scopeItemSnapshot')-ARRAY['approvedScopeVersion','scopeContentDigest']) IS DISTINCT FROM expected_item OR NEW.content->'scopeItemSnapshot'->>'scopeContentDigest' IS DISTINCT FROM NEW.scope_content_digest OR (NEW.content->'scopeItemSnapshot'->>'approvedScopeVersion')::bigint IS DISTINCT FROM NEW.approved_scope_version THEN RAISE EXCEPTION 'CASH_MOVEMENT_SCOPE_SNAPSHOT_STALE'; END IF;
 IF encode(sha256(original_row.content),'hex') IS DISTINCT FROM NEW.source_original_sha256 OR octet_length(original_row.content) IS DISTINCT FROM original_row.size_bytes THEN RAISE EXCEPTION 'CASH_MOVEMENT_ORIGINAL_INTEGRITY'; END IF;
 PERFORM 1 FROM plugin_finance_original o WHERE o.tenant_id=NEW.tenant_id AND o.book_id=NEW.book_id AND o.year_id=NEW.year_id AND o.id=scope_item.evidence_original_id AND o.sha256=scope_item.original_sha256 AND encode(sha256(o.content),'hex')=o.sha256 AND octet_length(o.content)=o.size_bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASH_MOVEMENT_SCOPE_EVIDENCE_STALE'; END IF;
 IF (NEW.content->>'sourceDocumentVersion')::integer IS DISTINCT FROM NEW.source_document_version OR (NEW.content->>'expectedScopeVersion')::bigint IS DISTINCT FROM NEW.approved_scope_version OR (NEW.content->>'lineNo')::integer IS DISTINCT FROM NEW.line_no OR (NEW.content->>'expectedJournalVersion')::bigint IS DISTINCT FROM NEW.matched_journal_version OR (NEW.content->>'expectedPostingSeq')::bigint IS DISTINCT FROM NEW.posting_seq OR NEW.content->>'schemaVersion' IS DISTINCT FROM NEW.schema_version OR coalesce(length(NEW.content->>'reason'),0) NOT BETWEEN 1 AND 1000 OR coalesce(length(NEW.content->>'description'),0) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'CASH_MOVEMENT_NUMERIC_SNAPSHOT_MISMATCH'; END IF;
 IF (NEW.content->'matchedLegSnapshot'->>'journalId',NEW.content->'matchedLegSnapshot'->>'accountId',NEW.content->'matchedLegSnapshot'->>'date',NEW.content->'matchedLegSnapshot'->>'direction',NEW.content->'matchedLegSnapshot'->>'postingDigest') IS DISTINCT FROM (NEW.journal_id::text,NEW.account_id::text,NEW.occurred_date::text,NEW.direction,NEW.posting_digest) OR (NEW.content->'matchedLegSnapshot'->>'lineNo')::integer IS DISTINCT FROM NEW.line_no OR (NEW.content->'matchedLegSnapshot'->>'journalVersion')::bigint IS DISTINCT FROM NEW.matched_journal_version OR (NEW.content->'matchedLegSnapshot'->>'postingSeq')::bigint IS DISTINCT FROM NEW.posting_seq OR (NEW.content->'matchedLegSnapshot'->>'normalizedAmount')::numeric IS DISTINCT FROM NEW.amount THEN RAISE EXCEPTION 'CASH_MOVEMENT_LEG_SNAPSHOT_MISMATCH'; END IF;
 IF (NEW.content->'matchedLegSnapshot'->>'number')::bigint IS DISTINCT FROM leg.number OR NEW.content->'matchedLegSnapshot'->>'summary' IS DISTINCT FROM leg.summary OR (NEW.content->'originalSnapshot'->>'version')::bigint IS DISTINCT FROM original_row.version OR (NEW.content->'originalSnapshot'->>'sizeBytes')::bigint IS DISTINCT FROM original_row.size_bytes OR NEW.content->'originalSnapshot'->>'mediaType' IS DISTINCT FROM original_row.media_type THEN RAISE EXCEPTION 'CASH_MOVEMENT_METADATA_SNAPSHOT_MISMATCH'; END IF;
 IF (NEW.content->>'tenantId',NEW.content->>'bookId',NEW.content->>'yearId',NEW.content->>'legalEntityId',NEW.content->>'preparedBy',NEW.content->>'sourceSystem',NEW.content->>'sourceMovementKey',NEW.content->>'sourceDocumentId',NEW.content->>'sourceRowReference',NEW.content->>'evidenceKind',NEW.content->>'cashScopeRevisionId',NEW.content->>'scopeContentDigest',NEW.content->>'accountId',NEW.content->>'occurredDate',NEW.content->>'direction',NEW.content->>'normalizedAmount',NEW.content->>'currency',NEW.content->>'transactionKind',NEW.content->>'journalId') IS DISTINCT FROM (NEW.tenant_id::text,NEW.book_id::text,NEW.year_id::text,NEW.legal_entity_id::text,NEW.prepared_by::text,NEW.source_system,NEW.source_movement_key,NEW.source_document_id,NEW.source_row_reference,NEW.evidence_kind,NEW.cash_scope_revision_id::text,NEW.scope_content_digest,NEW.account_id::text,NEW.occurred_date::text,NEW.direction,NEW.amount::text,NEW.currency,NEW.transaction_kind,NEW.journal_id::text) THEN RAISE EXCEPTION 'CASH_MOVEMENT_SNAPSHOT_MISMATCH'; END IF;
 IF (NEW.content->'originalSnapshot'->>'id',NEW.content->'originalSnapshot'->>'sha256',NEW.content->'originalSnapshot'->>'filename') IS DISTINCT FROM (NEW.source_original_id::text,NEW.source_original_sha256,original_row.filename) OR NEW.content->'scopeItemSnapshot'->'accountSnapshot' IS DISTINCT FROM scope_item.account_snapshot OR NEW.content->'accountSnapshot' IS DISTINCT FROM scope_item.account_snapshot THEN RAISE EXCEPTION 'CASH_MOVEMENT_EVIDENCE_SNAPSHOT_MISMATCH'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER finance_cash_movement_guard BEFORE INSERT OR UPDATE OR DELETE ON plugin_finance_cash_movement_registration FOR EACH ROW EXECUTE FUNCTION plugin_finance_cash_movement_guard();
